    "category": "E2",
    "title": "上所即被下架(基金经理)",
    "desc": "作为受托管理客户资金的基金经理，某项目的「日活跃用户（DAU）」数据被质疑造假：链上交互数据显示大量地址是合约自动创建的「僵尸账户」，没有真实人类行为特征（如交易时间分布异常、行为模式雷同）。真实 DAU 可能只有宣称的 10%。项目方用虚假 DAU 吸引投资和用户。你持有价值 22 万美元代币。面对这种「用户数据造假+虚假繁荣」的情况，你会？",
