    "desc": "仅剩12小时决策窗口且资金被锁定，某 GameFi 项目同时获得 a16z 和 Binance Labs 投资，两轮融资共 4000 万美元。团队来自育碧和 EA，游戏 Demo 已可试玩，画质堪比 3A 大作。但代币经济模型显示：团队+投资人解锁后占 70% 流通量，且解锁期仅 1 年。游戏预计 6 个月后上线。你会？",
