    "category": "B2",
    "title": "OTC折价40%(紧急决策)",
    "desc": "仅剩12小时决策窗口且资金被锁定，你投资的某DeFi协议国库拥有价值5000万美元的ETH，但协议收入仅能覆盖团队支出的60%，剩余40%需要靠卖币维持。按照当前支出速度，国库将在18个月内耗尽。团队表示正在开发新产品增加收入，但新产品开发周期通常12个月以上。你持有100万美元代币。面对这种「入不敷出+国库枯竭」的情况，你会？",
