    "desc": "作为受托管理客户资金的基金经理，某 Layer 2 网络的排序器（Sequencer）是中心化的，由项目方单一控制。虽然项目方承诺未来将去中心化，但目前所有交易都由该排序器确认。最近该网络出现 2 小时宕机，原因是排序器故障。你的 50 万美元资产在该网络上，虽然资金安全但无法操作。面对这种「中心化排序器+单点故障」的风险，你会？",
