    "category": "A3",
    "title": "后续轮估值暴涨(基金经理)",
    "desc": "作为受托管理客户资金的基金经理，某 DeFi 协议的流动性挖矿收益率异常高达 300% APY，但当你实际投入后发现，由于奖励代币价格持续下跌，实际收益率只有 20% APY。协议显示的收益率是基于奖励代币的「名义价格」计算的，而非实际可卖出的价格。你投入了 60 万美元。面对这种「名义收益+实际亏损」的情况，你会？",
