    "title": "审计发现逻辑错误(紧急决策)",
    "desc": "仅剩12小时决策窗口且资金被锁定，某 DeFi 协议的 Discord 管理员私聊你，说你是活跃用户，获得了「空投白名单」，需要你连接钱包到某个网站领取。该网站看起来与官方类似，但网址略有不同。社区里其他人也收到了类似消息。你持有该协议价值 25 万美元的代币。面对这种「假管理员+钓鱼网站」的诈骗，你会？",
