    "id": "V379",
    "category": "D1",
    "title": "国库大额转出(暴跌期)",
    "desc": "市场暴跌70%处于极度恐慌，你的加密货币投资已从 100 万增值到 800 万，是你总资产的 90%。你原本计划「赚够 500 万就收手」，但现在市场势头强劲，似乎还能继续涨。你面临「目标达成但贪婪作祟」的心理困境。同时你的家庭需要资金买房（首付 200 万）。你会？",
    "baseProfitPct": 0.5,
