    "id": "V397",
    "category": "C2",
    "title": "仅核心团队持股(紧急决策)",
    "desc": "仅剩12小时决策窗口且资金被锁定，某借贷协议的「清算机制」在极端行情下出现故障：大量借贷仓位应被清算但未被清算，导致协议产生巨额坏账。虽然你的仓位安全，但协议宣布所有存款人需要共同承担损失（社会化损失）。你的存款价值50万美元。面对这种「机制故障+社会化损失」的情况，你会？",
    "baseProfitPct": 1.4,
