    "explanation": "【启用备用-正确】单一 2FA 设备是风险点，设置备用设备和恢复码是必要的应急预案。这样即使手机丢失也能恢复账户访问。\n\n【改用硬件-次优】虽然更安全，但硬件密钥成本较高且需要携带。作为升级方案可以考虑，但首先应启用备用恢复方式。\n\n【多设备同步-次优】虽然提供冗余，但多设备增加攻击面，且同步过程可能暴露密钥。不如使用官方恢复码。\n\n【保持现状-错误】锁屏密码不能防止所有攻击（如 SIM 卡移植攻击）。单一设备是重大风险点。\n\n[变体说明：本场景为低估值长锁仓变体，源于原决策034-04，风险收益特征已相应调整]",
