    "category": "D2",
    "title": "团队要求追加投资(低估值版)",
    "desc": "估值便宜但锁仓期极长，你发现某 DeFi 协议的合约代码中有一个「紧急暂停」功能，允许管理员在紧急情况下冻结所有用户资金。虽然这可以防止黑客攻击造成的损失，但也意味着你的资产随时可能被单方面冻结。该协议管理着你 60 万美元的存款。面对这种「安全保护+冻结风险」的机制，你会？",
