    "explanation": "【寻找替代-正确】无限制升级权是重大安全隐患，管理员可以随时修改合约转走资金。应优先使用有时间锁或多签保护的去中心化桥。\n\n【小额过桥-次优】虽然降低单次风险，但如果需要大额转移，多次小额操作增加 Gas 成本和时间成本。不如找更安全的桥。\n\n【相信团队-错误】「知名」不等于「安全」。历史上知名项目滥用权限的案例很多，不应将资产安全寄托于信任。\n\n【分批过桥-错误】分批不能降低合约被恶意升级的风险，只是分散了锁定时间。风险本质未变。\n\n[变体说明：本场景为基金经理约束变体，源于原决策035-02，风险收益特征已相应调整]",
