    "id": "V526",
    "category": "C2",
    "title": "随意更改路线图(高估值版)",
    "desc": "估值偏高但流动性较好，某NFT市场的「智能合约」被黑，攻击者利用重入漏洞盗取了价值1000万美元的NFT。你的NFT并未被盗，但市场宣布暂停所有交易进行安全审计，时间未知。你的NFT估值8000万，急需流动性。面对这种「合约被黑+市场停摆」的情况，你会？",
