    "title": "社区自发组织活动(反弹期)",
    "desc": "急跌后反弹20%真假难辨，某项目声称「完全去中心化」，但链上数据显示 60% 的治理代币集中在团队和相关地址手中，且这些地址在关键投票中总是高度一致。实际上项目由少数人控制。你持有价值 40 万美元治理代币。面对这种「名义去中心化+实质中心化」的情况，你会？",
    "baseProfitPct": 2.6,
    "baseLossPct": 1.2,
    "choices": [
      {
        "text": "减仓退出：实质中心化违背区块链精神，项目价值存疑",
        "profitPct": 3.5,
        "lossPct": 1.6,
        "isCorrect": true
      },
      {
        "text": "继续持有：中心化不等于没价值，效率可能更高",
        "profitPct": 1.8,
        "lossPct": 1.1,
        "isCorrect": false
      },
      {
        "text": "联合小散户：积累足够票数影响治理",
        "profitPct": 0.6,
        "lossPct": 2.2,
        "isCorrect": false
      },
      {
        "text": "要求透明：在治理中要求披露真实控制情况",
        "profitPct": 0.6,
        "lossPct": 2.2,
        "isCorrect": false
      }
    ],
    "explanation": "【减仓退出-正确】60% 集中控制意味着「去中心化」只是营销话术，实质是中心化项目披了区块链的外衣。这种项目违背区块链核心价值，长期价值存疑。\n\n【继续持有-次优】虽然中心化可能带来效率，但「伪去中心化」是诚信问题。投资者被误导进入，一旦真相暴露价格可能崩盘。\n\n【联合小散户-错误】40% 分散在众多小散户手中，难以组织有效对抗。且团队可能通过利益诱导分化联盟。\n\n【要求透明-次优】虽然合理，但团队有动机维持「去中心化」假象，不太可能主动披露真实控制情况。\n\n[变体说明：本场景为反弹犹豫期变体，源于原决策044-01，风险收益特征已相应调整]",
    "originalId": "044-01",
    "variantRule": "反弹犹豫期"
