    "title": "市场恐慌抛售(高估值版)",
    "desc": "估值偏高但流动性较好，你的硬件钱包（Ledger）固件提示有更新，但更新需要连接电脑并输入 PIN 码。你最近看到新闻称 Ledger 的更新服务被黑客攻击，有用户因此丢失资产。你的硬件钱包里有 150 万美元。面对这种「固件更新+潜在风险」的情况，你会？",
