    "title": "专利持有者(低估值版)",
    "desc": "估值便宜但锁仓期极长，某跨链桥采用「乐观验证」机制：假设交易有效，除非有人提交欺诈证明。挑战窗口期为7天，期间资金被锁定。你担心7天窗口期太长，且如果有人恶意挑战可能导致资金延迟。你计划桥接50万美元。面对这种「乐观验证+挑战风险」的机制，你会？",
