    "desc": "作为受托管理客户资金的基金经理，某项目推出「预测市场」，用户可以押注未来事件的结果。但市场流动性很差，大额订单会产生巨大价格冲击。且项目方收取2%的手续费。你计划投入20万美元预测某事件。面对这种「低流动性+高手续费」的市场，你会？",
    "baseProfitPct": 0.9,
