    "title": "锁仓期间无治理权(紧急决策)",
    "desc": "仅剩12小时决策窗口且资金被锁定，你参与了某项目的IDO，代币解锁后价格跌80%，深度套牢。项目方称在持续「build」，但交付 repeatedly 延期，路线图上的功能迟迟未实现，社区气氛低迷，信心丧失。面对这种「深度亏损+进展缓慢」的情况，你会？",
