    "category": "A3",
    "title": "开曼基金会(紧急决策)",
    "desc": "仅剩12小时决策窗口且资金被锁定，某项目方声称「开源」，但核心算法库使用了混淆编译，无法被审计。项目方称这是「保护商业机密」，但开源社区质疑这是隐藏后门。你持有价值 20 万美元代币。面对这种「名义开源+实质封闭」的情况，你会？",
